import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(this));
        // capture the owner state before the boundary call via the public getter
        address ownerBefore = c.owner();
        // drive the entry point `owned` from an arbitrary fuzzed actor
        vm.prank(actor);
        bool ok;
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: owned() never mutates the owner — it either reverts
        // (unauthorized caller) or, when it completes, owner() is unchanged.
        assertTrue(!ok || c.owner() == ownerBefore);
    }
}

